CREATE OR REPLACE FUNCTION public.starter_kit(p_world uuid, p_uid uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
begin
  perform kit_topup(p_world, p_uid);
  -- And the stake, which is the only thing in the kit that is not a tool, and only the first time.
  insert into item (world_id, holder, holder_uid, def, ql, extra)
  values (p_world, 'player', p_uid, 'deed_stake', 50, 'Pine');
  -- And food, the first time only: a full food bar of cheese at the kit's QL (`STARTER_FOOD`).
  insert into item (world_id, holder, holder_uid, def, ql, count)
  values (p_world, 'player', p_uid, 'cheese', 20, 5);
end $function$
